import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BTLSZHNB.js";const h=JSON.parse('{"title":"Takoform portable specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/overview.md","filePath":"spec/overview.md"}'),i={name:"spec/overview.md"};function n(c,e,s,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="takoform-portable-specification" tabindex="-1">Takoform portable specification <a class="header-anchor" href="#takoform-portable-specification" aria-label="Permalink to &quot;Takoform portable specification&quot;">​</a></h1><p>This directory is the portable specification surface for Takoform, an <strong>Experimental specification and tooling project</strong>. Takoform defines a small desired-state boundary between infrastructure-as-code clients and resource hosts; it is not currently an industry standard, certification authority, or guarantee of backend portability.</p><p>Requirement keywords, conformance classes, and what a passing check does and does not prove are defined in <a href="./conformance.html"><code>conformance.md</code></a>. How the API group, Forms, packages, and the provider are versioned is in <a href="./versioning.html"><code>versioning.md</code></a>. Current project positioning and the Proposal → Experimental → Stable → Legacy lifecycle are defined in <a href="./project-lifecycle.html"><code>project-lifecycle.md</code></a>. The exact boundary between portable workload semantics and host/profile/operator concerns is <a href="./portability-boundary.html"><code>portability-boundary.md</code></a>.</p><h2 id="product-contract-map" tabindex="-1">Product contract map <a class="header-anchor" href="#product-contract-map" aria-label="Permalink to &quot;Product contract map&quot;">​</a></h2><p>Takoform has five public contract interfaces:</p><ol><li><strong>Exact Form and Package data.</strong><a href="./form-definition/"><code>form-definition/</code></a> defines immutable <code>FormRef</code> and the desired/observed/output shape. <a href="./form-package/"><code>form-package/</code></a> binds one exact definition and its data-only fixtures into immutable package bytes.</li><li><strong>Desired Resource lifecycle.</strong><a href="./host-api/"><code>host-api/</code></a> defines discovery, exact Form availability, preview/apply, read/import/observe/refresh/delete, fencing, and portable errors. The host chooses implementation and placement.</li><li><strong>Read-only Form-derived Interface projection.</strong><a href="./interface-declaration/"><code>interface-declaration/</code></a> defines open <code>(name, version)</code> descriptors embedded in Forms and their read-only host projection. Focused contracts such as the Legacy <a href="./data-indexed/"><code>data.indexed@1</code></a> only define the descriptor data the declaring Form actually declares.</li><li><strong>Current-lane (Edge Platform Family) contract surfaces.</strong><a href="./host-api/v1alpha3.html"><code>host-api/v1alpha3.md</code></a> defines the current Host API lane with UID/generation/revision resource identity, long-running Operations, and Host Support Profiles. <a href="./form-families.html"><code>form-families.md</code></a> defines namespaced Form Family groups. <a href="./interface-contract/"><code>interface-contract/</code></a> defines exact digest-bound Interface contracts, <a href="./binding-contract/"><code>binding-contract/</code></a> defines typed Binding contracts, and <a href="./artifact-transport/"><code>artifact-transport/</code></a> defines content-addressed artifact upload.</li><li><strong>Trust, lifecycle, version, and release identity.</strong><a href="./trust/"><code>trust/</code></a> defines immutable publisher evidence and revocation; <a href="./project-lifecycle.html"><code>project-lifecycle.md</code></a> separates Form maturity from Host Support and availability; <a href="./versioning.html"><code>versioning.md</code></a> keeps provider, API, Form, and package compatibility independent. <a href="./../release/"><code>release/</code></a> binds artifacts to those exact identities without changing the contracts above.</li></ol><p><a href="./schemas/"><code>schemas/</code></a>, <a href="./conformance.html"><code>conformance.md</code></a>, and <a href="./decisions/"><code>decisions/</code></a> support those interfaces with structural minima, executable evidence language, and decision rationale. They are not additional product interfaces. The generated current inventory is <a href="./../forms/"><code>../forms/README.md</code></a>, host discovery validation is <a href="/schemas/host-discovery.schema.json"><code>../schemas/host-discovery.schema.json</code></a>, and the local evidence map is <a href="./../conformance/"><code>../conformance/README.md</code></a>.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>The FormRef, Form Definition, package-index, revocation, and cumulative revocation-checkpoint schemas, the RFC 8785/I-JSON library, the closed local verifier, the positive/negative corpus, the protected keyless Sigstore release lane, and the signed append-only checkpoint delivery lane are implemented.</p><p>Current Form design work uses namespaced Form Family groups (<a href="./form-families.html"><code>form-families.md</code></a>); the first family is <code>edge.forms.takoform.com/v1alpha1</code> and its packages use <code>packages.forms.takoform.com/v1alpha4</code>. The <code>forms.takoform.com/v1alpha2</code> epoch and its nine <code>0.1.0</code> source candidates are retained provider-v2 preview source under the <code>packages.forms.takoform.com/v1alpha3</code> envelope (<a href="./decisions/0013-v1alpha3-lane-ships-in-provider-v2-1.html">decision 0013</a>); they are not the basis for new specification work. A repository implementation or local passing gate is not Form publication, Host Support, activation, or live Cloud availability.</p><p>Decision <a href="./decisions/0004-takoform-is-an-experimental-specification.html"><code>0004</code></a> made the previously published <code>forms.takoform.com/v1alpha1</code> line Legacy after it was labelled <code>standard</code> without sufficient independent implementation and operational evidence. Decision <a href="./decisions/0006-v1alpha2-restarts-form-lines.html"><code>0006</code></a> restarts selected kinds in the distinct v1alpha2 epoch through mutable Proposals and Experimental <code>0.x</code> Forms. Decision <a href="./decisions/0007-current-forms-exclude-substrate-operation.html"><code>0007</code></a> requires those candidates to be independently authored and excludes substrate operation from portable desired state. Historical <code>standard</code> and <code>portable-standard</code> fields remain readable in immutable documents; they do not define a current approved subset. The lifecycle projection and Legacy verification tooling are implemented and fail closed against <a href="../forms/lifecycle.json"><code>../forms/lifecycle.json</code></a>. Generated compatibility inventory pages classify every retained entry as Legacy and MUST NOT reinterpret historical package or admission fields as current project status.</p><p>Published generations are retained, not erased. Their immutable releases and admission evidence stay verifiable offline through <a href="../forms/retired-package-set.json"><code>../forms/retired-package-set.json</code></a>, and the current retained release sets. This build refuses to overwrite or restamp their proofs with a new provider or maturity identity.</p><p>The frozen Legacy Host API wire remains <code>forms.takoform.com/v1alpha1</code>, and the retained provider-v2 wire remains <code>forms.takoform.com/v1alpha2</code> at <code>/.well-known/takoform/v1alpha2</code>. The current Host API wire is <code>forms.takoform.com/v1alpha3</code>, reached through its own discovery path <code>/.well-known/takoform/v1alpha3</code> so retained clients cannot select the current API accidentally. The Host API group is a protocol compatibility identity independent of any nested Form group. The current package envelope is <code>packages.forms.takoform.com/v1alpha4</code>. The Terraform provider identity is <code>registry.terraform.io/tako0614/takoform</code>; its SemVer is independent from all of these API identities.</p><h2 id="normative-consistency-audit" tabindex="-1">Normative consistency audit <a class="header-anchor" href="#normative-consistency-audit" aria-label="Permalink to &quot;Normative consistency audit&quot;">​</a></h2><p><code>go test ./spec</code> is the cross-specification contradiction gate. It does not repeat the Form Package verifier, provider schema tests, or portable-host runner. Instead, it joins their machine-readable inputs and fails when:</p><ul><li>host operations, mutation fences, idempotency, or the stable error taxonomy disagree with the portable-host conformance contract;</li><li>the optional Interface projection stops being read-only, same-origin, and materialized only from Form-declared descriptors;</li><li>the portable API identity, provider candidate version, or canonical provider FQN diverges between release, schema, trust, and conformance locks; or</li><li>a normative active Form, package, schema, or host contract leaks a concrete backend vocabulary such as Cloudflare/Workers configuration.</li></ul><p>The complete repository gate, <code>bun run check</code>, runs this audit together with the deeper package-byte, provider-schema, generated-surface, and lifecycle verifiers. Passing it remains local evidence only; it does not prove Registry publication, Host Support, Form maturity, production activation, or interoperability.</p>',17)])])}const f=o(i,[["render",n]]);export{h as __pageData,f as default};
